CREATE OR REPLACE FUNCTION public.mha_admin_company_store_catalog()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n if auth.uid() is null or not exists(select 1 from public.mha_super_admin_identity sa join public.mha_user_profile u on u.user_id=sa.user_id where sa.user_id=auth.uid() and u.is_active and u.is_super_admin) then\n  raise exception 'Super Admin access required' using errcode='42501';\n end if;\n return jsonb_build_object(\n  'companies',coalesce((select jsonb_agg(jsonb_build_object('id',id,'company_code',company_code,'company_name',company_name,'is_active',is_active) order by company_code) from public.mha_company),'[]'::jsonb),\n  'stores',coalesce((select jsonb_agg(jsonb_build_object('id',id,'company_id',company_id,'store_code',store_code,'store_name',store_name,'public_slug',public_slug,'is_active',is_active) order by company_id,store_code) from public.mha_store),'[]'::jsonb)\n );\nend $function$\n

-- Explicit least-privilege grants are required on a fresh migration replay.
REVOKE ALL ON FUNCTION public.mha_admin_company_store_catalog() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mha_admin_company_store_catalog() TO authenticated;
